import{_ as e,o as s,c as i,a1 as n}from"./chunks/framework.CblolBb6.js";const t="/Pelatihan-WebGIS-BIG/assets/image17.-FIkILDO.png",l="/Pelatihan-WebGIS-BIG/assets/image7.C4P0GxSq.png",r="/Pelatihan-WebGIS-BIG/assets/image4.DSrrWLU6.png",p="/Pelatihan-WebGIS-BIG/assets/image2.BRH8U_38.png",o="/Pelatihan-WebGIS-BIG/assets/image6.D99rURRt.png",g="/Pelatihan-WebGIS-BIG/assets/image22.B05Ue1-q.png",m="/Pelatihan-WebGIS-BIG/assets/image13.DEb4RGU5.png",u="/Pelatihan-WebGIS-BIG/assets/image26.Co1Oi0KU.png",d="/Pelatihan-WebGIS-BIG/assets/image23.nB62hO2I.png",k="/Pelatihan-WebGIS-BIG/assets/image15.DSCYnF9e.png",h="/Pelatihan-WebGIS-BIG/assets/image9.Ba2k93Gb.png",c="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4XmP4//8/AwAI/AL+GwXmLwAAAABJRU5ErkJggg==",b="/Pelatihan-WebGIS-BIG/assets/image14.BtNJ7tX2.png",I="/Pelatihan-WebGIS-BIG/assets/image18.zXpiNJYJ.png",_="/Pelatihan-WebGIS-BIG/assets/image25.JfOWb66U.png",G="/Pelatihan-WebGIS-BIG/assets/image11.HQMJtj_g.png",S="/Pelatihan-WebGIS-BIG/assets/image1.I5i0oN1G.png",B="/Pelatihan-WebGIS-BIG/assets/image3.DYYG86JB.png",f="/Pelatihan-WebGIS-BIG/assets/image10.DtKf98ss.png",P="/Pelatihan-WebGIS-BIG/assets/image24.BAM1JXqh.png",A="/Pelatihan-WebGIS-BIG/assets/image19.CsS4hsZ9.png",v="/Pelatihan-WebGIS-BIG/assets/image12.Bsgc0Zg6.png",w="/Pelatihan-WebGIS-BIG/assets/image16._1aMX8og.png",y="/Pelatihan-WebGIS-BIG/assets/image21.CME-rXLN.png",R=JSON.parse('{"title":"Instalasi Aplikasi","description":"","frontmatter":{},"headers":[],"relativePath":"hari-1/persiapan-lingkungan/instalasi-aplikasi.md","filePath":"hari-1/persiapan-lingkungan/instalasi-aplikasi.md"}'),q={name:"hari-1/persiapan-lingkungan/instalasi-aplikasi.md"};function W(j,a,J,x,D,N){return s(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="instalasi-aplikasi" tabindex="-1">Instalasi Aplikasi <a class="header-anchor" href="#instalasi-aplikasi" aria-label="Permalink to &quot;Instalasi Aplikasi&quot;">​</a></h1><p><strong>Modul 1 - Dasar-Dasar GIS, Konsep WebGIS, Dasar Pemrograman, dan Github</strong></p><h2 id="instalasi-visual-studio-code-git-dan-node-js" tabindex="-1"><strong>Instalasi Visual Studio Code, Git dan Node.js</strong> <a class="header-anchor" href="#instalasi-visual-studio-code-git-dan-node-js" aria-label="Permalink to &quot;**Instalasi Visual Studio Code, Git dan Node.js**&quot;">​</a></h2><ol><li><p>Buka tautan <a href="https://code.visualstudio.com/download" target="_blank" rel="noreferrer">https://code.visualstudio.com/download</a>, kemudian pilih opsi unduh berdasarkan sistem operasi yang digunakan.</p><p><img src="'+t+'" alt=""></p></li><li><p>Tahapan berikutnya setelah proses unduh selesai, maka lakukan proses instalasi kemudian tunggu hingga proses instalasi selesai. Berikut ini merupakan tampilan awal dari Virtual Studio Code.</p><p><img src="'+l+'" alt=""></p></li><li><p>Selanjutnya unduh git melalui tautan berikut ini <a href="https://git-scm.com/" target="_blank" rel="noreferrer">https://git-scm.com/</a> untuk mengelola repository project , kemudian lakukan proses instalasi git tersebut.</p><p><img src="'+r+'" alt=""></p></li><li><p>Tahapan berikutnya instal Node.js yang akan digunakan sebagai package manager untuk melakuan pemrograman menggunakan Javascript, Next.js, Angular serta bahasa pemrograman javascript lainnya. Node.js dapat diunduh pada link berikut ini <a href="https://nodejs.org/en/download" target="_blank" rel="noreferrer">https://nodejs.org/en/download</a>.</p><p><img src="'+p+'" alt=""></p></li><li><p>Setelah proses instalasi Git dan Node.js telah selesai, untuk melihat apakah proses instalasi telah selesai dan terpasang pada perangkat yang digunakan, pengguna dapat melakukan pengecekan pada Windows Powershell kemudian melakukan pengetikan perintah git version untuk melihat versi git yang telah di install serta node --version untuk melihat versi node yang telah di install.</p></li></ol><p><img src="'+o+'" alt=""></p><h2 id="instalasi-postgresql" tabindex="-1"><strong>Instalasi Postgresql</strong> <a class="header-anchor" href="#instalasi-postgresql" aria-label="Permalink to &quot;**Instalasi Postgresql**&quot;">​</a></h2><ol><li><p>Buka tautan <a href="https://www.postgresql.org/" target="_blank" rel="noreferrer">https://www.postgresql.org/</a> kemudian klik menu download lalu pilih sesuai dengan sistem operasi yang digunakan oleh pengguna.</p><p><img src="'+g+'" alt=""></p></li><li><p>Tahapan berikutnya lakukan proses instalasi postgresql berdasarkan hasil yang telah diunduh pada perangkat.</p><p><img src="'+m+'" alt=""></p></li><li><p>Setelah tahapan instalasi selesai maka akan muncul tampilan untuk stackbuilder kemudian pilih Postgresql 18 (x64).</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya pilih mn instalasi exstensi untuk mendukung penyimpanan data dalam bentuk spasial dengan memilih library postgis.</p><p><img src="'+d+'" alt=""></p></li><li><p>Setelah tahapan instalasi selesai,buka pgadmin untuk melihat tampilan dari Postgresql yang telah terpasang pada perangkat pengguna.</p><p><img src="'+k+'" alt=""></p></li></ol><h2 id="instalasi-geoserver" tabindex="-1"><strong>Instalasi Geoserver</strong> <a class="header-anchor" href="#instalasi-geoserver" aria-label="Permalink to &quot;**Instalasi Geoserver**&quot;">​</a></h2><ol><li><p>Buka tautan <a href="https://geoserver.org/" target="_blank" rel="noreferrer">https://geoserver.org/</a> kemudian klik menu download lalu pilih versi geoserver yang akan digunakan, kemudian unduh installer geoserver.</p><p><img src="'+h+'" alt=""></p><p><img src="'+c+'" alt=""></p></li><li><p>Setelah selesai download anda bisa menjalankan file installer kemudian saat proses instalasi akan bertemu halaman berikut ini. Klik Visit Adoptium OpenJDK website untuk download JRE 17 kemudian install</p><p><img src="'+b+'" alt=""></p></li><li><p>Jika sudah install JRE 17, biasanya terinstall di folder C:/Program Files/Eclipse Adoptium/jdk-17.0.20.101-hotspot. Kembali ke installer geoserver dan arahkan folder JRE 17 ke folder hasil instalasi JRE 17. Lanjutkan proses instalasi sampai selesai gunakan semua opsi default saja</p><p><img src="'+I+'" alt=""></p></li><li><p>Selanjutnya setelah geoserver terinstall, untuk mengaktifkangeoserver yang akan digunakan dilakukan dengan cara membuka aplikasi dengan nama Start Geoserver.</p><p><img src="'+_+'" alt=""></p></li><li><p>Tahapan berikutnya setelah mengaktifkan geoserver, maka pengguna dapat membukanya pada browser dengan tautan port berikut ini <a href="http://localhost:8080/geoserver/web/?0" target="_blank" rel="noreferrer">http://localhost:8080/geoserver/web/?0</a>. Berikut ini tampilan geoserver.</p><p><img src="'+G+'" alt=""></p></li><li><p>Selanjutnya pengguna bisa untuk masuk kehalaman login menggunakan akun admin yang telah dibuat pada proses install geoserver.</p><p><img src="'+S+'" alt=""></p></li><li><p>Berikut ini merupakan hasil tampilan ketika selesai proses login sebagai admin pada geoserver.</p><p><img src="'+B+'" alt=""></p></li><li><p>Jika pengguna ingin menonaktifkan geoserver, pengguna dapat memilih menu Stop Geosever, maka geosever akan nonaktif.</p><p><img src="'+f+'" alt=""></p></li></ol><h2 id="instalasi-qgis" tabindex="-1"><strong>Instalasi QGIS</strong> <a class="header-anchor" href="#instalasi-qgis" aria-label="Permalink to &quot;**Instalasi QGIS**&quot;">​</a></h2><ol><li><p>Buka tautan berikut ini <a href="https://qgis.org/download/" target="_blank" rel="noreferrer">https://qgis.org/download/</a> kemudian pilih menu download sesuai dengan metode sistem operasi yang digunakan oleh peserta.</p><p><img src="'+P+'" alt=""></p></li><li><p>Selanjutnya setelah selesai mengunduh installer perangkat lunak QGIS, buka installer tersebut maka akan terdapat tampilan berikut ini kemudian klik next.</p><p><img src="'+A+'" alt=""></p></li><li><p>Tahapan berikutnya klik next hingga muncul proses installasi.</p><p><img src="'+v+'" alt=""></p></li><li><p>Setelah proses instalasi selesai, buka file qgis desktop.</p><p><img src="'+w+'" alt=""></p><p><img src="'+y+'" alt=""></p></li></ol>',11)])])}const U=e(q,[["render",W]]);export{R as __pageData,U as default};
